namespace Site {

using namespace Botanik;

/**
 * @brief The four roof windows: one target from the cooling ladder, and ONE
 *        MOVING AT A TIME.
 *
 * `windows`, dispatched SLOW. Everything here is declared in
 * tables/programs.toml; the body is hand-written beside this file. A name
 * without a leading underscore is a row or a block the POU is connected to;
 * one with is its own.
 */
class WindowsController final : public Plc::Program {

public:

    /** @name VAR_INPUT
     *  @{ */

    Vars::RefIn<float>    window_dem;
    Vars::RefIn<float>    rain_mmph;
    Vars::RefIn<float>    wind_mps;
    Vars::RefIn<float>    gust_mps;
    Vars::RefIn<float>    wind_shut;
    Vars::RefIn<uint16_t> rain_hold_s;
    Vars::RefIn<uint16_t> travel_s;
    Vars::RefIn<uint16_t> tmo_s;
    Vars::RefIn<bool>     supply_lock;

    /** @} */

    /** @name VAR_OUTPUT
     *  @{ */

    Vars::RefOut<bool>  opn[4];
    Vars::RefOut<bool>  clo[4];
    Vars::RefOut<float> tgt[4];
    Vars::RefOut<float> pos[4];

    /** @} */

    /** @name VAR_IN_OUT
     *  @{ */

    Vars::RefInOut<bool> rain_lock;
    Vars::RefInOut<bool> wind_lock;
    Vars::RefInOut<bool> window_lock;

    /** @} */

private:

    /** @name VAR - function blocks
     *  @{ */

    Plc::Actuator act[4];
    Plc::Tof      rain_for;  ///< the rain lockout's overrun past the last drop

    /** @} */

    /** @name VAR - what this law remembers
     *  @{ */

    float _target = 0.0f;     ///< The position the arbitration asked for this scan. One number for all four: they are one roof.
    float _safe_open = 0.0f;  ///< Where the roof goes when this law is not acting: PART OPEN, not shut, read off the target row's declared default like every other safe state here. It should never be reached, but a greenhouse with some ventilation survives a summer afternoon and a sealed one does not. @note NOT the interlocks: rain and wind shut the roof outright.

    /** @} */

    /** @name Sizes
     *  How many rows or instances each array member has, from the
     *  table. What a body loops over, so a site constant cannot get
     *  out of step with what is declared.
     *  @{ */

    static const uint8_t N_OPN = 4;
    static const uint8_t N_CLO = 4;
    static const uint8_t N_TGT = 4;
    static const uint8_t N_POS = 4;
    static const uint8_t N_ACT = 4;

    /** @} */

    /** @brief Every readable row this program connects to, as bare
     *  indices: what the base sweeps for validity before each
     *  activation. Parameters are not here - an operator's number is
     *  always valid, and checking one would cost a walk to learn nothing. */
    Vars::VarRef _watched[8];

public:
    /** @brief The instance name and rate class programs.toml
     *  declares, so neither can drift from the configuration. */
    WindowsController(const SetupContext& ctx, Vars::Bank& io)
        : Program(ctx, "windows", Tasks::GROUP_SLOW, io) {}

protected:
    /** @brief Resolve every name. Runs inside the program's writer
     *  window, so an output is CLAIMED here. */
    void bind(Vars::Bank& io) override;

    /** @brief One activation of the law. */
    void run(ProgramContext& c) override;

    /** @brief What this program SAYS, in every state - including
     *  while the plant is parked. */
    void observe(ProgramContext& c) override;

    /** @brief What the law wires once the rows are resolved: a block
     *  taking a reference, a fail direction read off a row. */
    void on_bind();

private:

    /** @brief The mechanics, rebuilt each scan from the parameters: a recalibrated travel time has to land on the next stroke, not the next boot. */
    Plc::ActuatorConfig _mechanics() const;
    /** @brief Whether anything forbids the windows being open at all. Publishes the two reasons it owns. */
    bool                _shut_in(ProgramContext& c);
    /** @brief Which window may move this scan, or -1. */
    int8_t              _owner(float target, const Plc::ActuatorConfig& cfg) const;
};

inline void WindowsController::bind(Vars::Bank& io) {
    window_dem  = io.resolve_in<float>("cli_windowDem");
    rain_mmph   = io.resolve_in<float>("cli_rain_mmph");
    wind_mps    = io.resolve_in<float>("cli_wind_mps");
    gust_mps    = io.resolve_in<float>("cli_windGust_mps");
    wind_shut   = io.resolve_in<float>("cli_windShut_mps");
    rain_hold_s = io.resolve_in<uint16_t>("cli_rainLockout_sec");
    travel_s    = io.resolve_in<uint16_t>("cli_windowTravel_sec");
    tmo_s       = io.resolve_in<uint16_t>("cli_windowTmo_sec");
    supply_lock = io.resolve_in<bool>("sys_supply_lockout");
    opn[0]      = io.resolve_out<bool>("cli_window1_opn");
    opn[1]      = io.resolve_out<bool>("cli_window2_opn");
    opn[2]      = io.resolve_out<bool>("cli_window3_opn");
    opn[3]      = io.resolve_out<bool>("cli_window4_opn");
    clo[0]      = io.resolve_out<bool>("cli_window1_clo");
    clo[1]      = io.resolve_out<bool>("cli_window2_clo");
    clo[2]      = io.resolve_out<bool>("cli_window3_clo");
    clo[3]      = io.resolve_out<bool>("cli_window4_clo");
    tgt[0]      = io.resolve_out<float>("cli_window1_tgt");
    tgt[1]      = io.resolve_out<float>("cli_window2_tgt");
    tgt[2]      = io.resolve_out<float>("cli_window3_tgt");
    tgt[3]      = io.resolve_out<float>("cli_window4_tgt");
    pos[0]      = io.resolve_out<float>("cli_window1_pos");
    pos[1]      = io.resolve_out<float>("cli_window2_pos");
    pos[2]      = io.resolve_out<float>("cli_window3_pos");
    pos[3]      = io.resolve_out<float>("cli_window4_pos");
    rain_lock   = io.resolve_inout<bool>("cli_rainLockout");
    wind_lock   = io.resolve_inout<bool>("cli_windLockout");
    window_lock = io.resolve_inout<bool>("cli_windowLockout");

    // The readings this law is entitled to expect. The base walks them
    // before each activation, so an input that has stopped being believable
    // is DEGRADED whether or not the law thought to ask.
    _watched[0] = window_dem.r;
    _watched[1] = rain_mmph.r;
    _watched[2] = wind_mps.r;
    _watched[3] = gust_mps.r;
    _watched[4] = supply_lock.r;
    _watched[5] = rain_lock.r;
    _watched[6] = wind_lock.r;
    _watched[7] = window_lock.r;
    set_inputs(_watched, 8);
    set_health_row(io.resolve_out<uint8_t>("prog_windows"));
    on_bind();
}

}  // namespace Site

#endif // SITE_PROGRAM_WINDOWS_CONTROLLER_GEN_H
